sys_script_client.script:
function onLoad() {
    if (g_scratchpad.blkTskRelated == 'Maker') { // Added condition for MSSCUSTODY-7570
        var market = g_scratchpad.ownB;
        if ((market == 'DCC UK') || (market == 'GC UK')) {
            g_form.removeOption('cancel_by', 'B');
        } else {
            g_form.removeOption('cancel_by', 'G');
            g_form.removeOption('cancel_by', 'M');
            //g_form.removeOption('cancel_by','N'); 
        }

        //MSSCUSTODY-7042
        // Commented below script as part of MSSCUSTODY-7241
        var outcome = g_form.getValue('outcome');
        if (outcome == "Settle Trade") {
            g_form.setValue('settlement_type', 'B');
        }
        if (outcome == "Process Trade Cancellation") {
            g_form.setValue('cancel_by', 'C');
        }
    }
}
